import {requireUploadAccess} from './upload-auth.js';
const angles=[['front','正面'],['left45','左侧 45°'],['right45','右侧 45°'],['left','左侧面'],['right','右侧面']],pending=new Map(),cards=new Map(),urls=new Map();const status=document.querySelector('#status'),save=document.querySelector('#save'),progress=document.querySelector('#progress');let busy=false;
function controls(){save.disabled=busy||!pending.size;for(const card of cards.values())card.querySelector('input').disabled=busy;}
for(const [angle,label] of angles){const card=document.createElement('section');card.className='photo';card.innerHTML=`<h2>${label}</h2><div class="preview">尚未上传</div><label for="photo-${angle}">选择照片</label><input id="photo-${angle}" type="file" accept="image/jpeg,image/png,image/webp"><p class="detail">JPG、PNG、WebP，每张最大 20MB</p>`;cards.set(angle,card);document.querySelector('#photos').append(card);card.querySelector('input').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!/\.(jpe?g|png|webp)$/i.test(file.name)||file.size>20*1024*1024){status.textContent='请选择 20MB 以内的 JPG、PNG 或 WebP 照片。HEIC 请先导出为 JPG。';e.target.value='';return;}pending.set(angle,file);if(urls.has(angle))URL.revokeObjectURL(urls.get(angle));const url=URL.createObjectURL(file);urls.set(angle,url);show(card,url,file.name+' · 待保存');status.textContent=`已选择 ${pending.size} 张照片，可以一起保存。`;controls();};}
function show(card,url,text){const img=document.createElement('img');img.alt=card.querySelector('h2').textContent;img.src=url;card.querySelector('.preview').replaceChildren(img);card.querySelector('.detail').textContent=text;}
async function refresh(){const r=await fetch('/api/portrait-reference',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error);for(const item of d.photos){if(!pending.has(item.angle))show(cards.get(item.angle),item.preview,`${item.name} · ${item.width} × ${item.height} · 已保存`);}document.querySelector('#count').textContent=`服务端已保存 ${d.savedAngles} / 5 个角度`;return d;}
function upload(angle,file,onprogress){return new Promise((resolve,reject)=>{const x=new XMLHttpRequest();x.open('POST','/api/portrait-reference');x.timeout=120000;x.setRequestHeader('Content-Type',file.type||'application/octet-stream');x.setRequestHeader('X-Photo-Angle',angle);x.setRequestHeader('X-Photo-Name',encodeURIComponent(file.name));x.upload.onprogress=e=>{if(e.lengthComputable)onprogress(e.loaded);};x.onload=()=>{let d;try{d=JSON.parse(x.responseText);}catch{}if(x.status===201)resolve(d);else reject(Error(d?.error||`上传失败（${x.status}）`));};x.onerror=x.ontimeout=()=>reject(Error('上传连接中断，已保存的照片不会丢失。请重试。'));x.send(file);});}
save.onclick=async()=>{if(busy||!pending.size)return;busy=true;controls();progress.hidden=false;progress.value=0;const entries=[...pending],total=entries.reduce((n,[,file])=>n+file.size,0);let completed=0;try{await requireUploadAccess();for(const [angle,file] of entries){status.textContent=`正在上传${cards.get(angle).querySelector('h2').textContent}：${file.name}`;await upload(angle,file,loaded=>{progress.value=Math.min(99,(completed+loaded)/total*100);});completed+=file.size;pending.delete(angle);}progress.value=100;await refresh();status.textContent='所选照片已保存在服务端，待面部重建。';}catch(e){status.textContent=e.message;await refresh().catch(()=>{});}finally{busy=false;controls();}};
try{await requireUploadAccess();await refresh();status.textContent='请选择照片，或补充尚未上传的角度。';}catch(e){status.textContent=e.message;}controls();
